window.QUESTION_POOLS = window.QUESTION_POOLS || {};
window.QUESTION_POOLS['aplus1'] = [
  { q: 'A laser printer is producing faint ghost images from previous print jobs. Which component is most likely failing?', opts: ['Toner cartridge', 'Fuser assembly', 'Imaging drum', 'Transfer belt'], answer: 1, exp: 'Ghost images (shadow of previous pages) indicate a worn fuser that is not cleaning up residual toner between passes. Replace the fuser assembly.', domain: 'D3' },
  { q: 'Which RAID level provides the best read/write performance with NO fault tolerance?', opts: ['RAID 0', 'RAID 1', 'RAID 5', 'RAID 10'], answer: 0, exp: 'RAID 0 stripes data across all drives for maximum performance but provides zero redundancy. Loss of any single drive destroys the entire array.', domain: 'D3' },
  { q: 'A user\'s PC displays 169.254.x.x as its IP address. What is the most likely cause?', opts: ['Static IP configuration error', 'DHCP server unreachable (APIPA assigned)', 'DNS resolution failure', 'Incorrect subnet mask'], answer: 1, exp: '169.254.x.x is APIPA (Automatic Private IP Addressing), assigned automatically when a DHCP server cannot be reached. Check network connection, DHCP server, and DHCP relay agent.', domain: 'D2' },
  { q: 'A user cannot print to a network printer. Other users on the same subnet print fine. What is the FIRST step?', opts: ['Replace the printer', 'Check that the user\'s PC has the correct printer driver installed', 'Restart the print spooler on the server', 'Verify the printer IP address'], answer: 1, exp: 'Since only one user is affected and others work fine, the issue is likely client-side. Check the printer driver (wrong driver = failure), IP/port configuration in the printer properties, and ensure the printer is set as default.', domain: 'D2' },
  { q: 'A technician is replacing a CPU cooler. What should they do before installing the new cooler?', opts: ['Update BIOS first', 'Clean old thermal paste and apply fresh thermal compound', 'Discharge the CPU with a resistor', 'Format the OS drive'], answer: 1, exp: 'Dried or improperly applied thermal paste reduces heat transfer, causing overheating. Always clean old paste (isopropyl alcohol) and apply fresh compound before installing any new cooler.', domain: 'D3' },
  { q: 'A Windows PC cannot connect to websites by name but works fine when using IP addresses. What is broken?', opts: ['Default gateway', 'DNS resolution', 'DHCP scope', 'Network interface driver'], answer: 1, exp: 'If IP access works but name resolution fails, DNS is the problem. Check: ipconfig /all (verify DNS server IP), flush DNS cache (ipconfig /flushdns), and test with nslookup.', domain: 'D2' },
  { q: 'A user reports that their laptop screen is very dim but visible when using a flashlight to view the display. What has failed?', opts: ['LCD panel', 'GPU driver', 'Backlight/backlight inverter', 'Video cable'], answer: 2, exp: 'If content is visible but very dim, the display panel is fine but the backlight (LED or CCFL backlight + inverter for older LCDs) has failed. GPU and cable issues typically cause no image or distortion.', domain: 'D1' },
  { q: 'What is the maximum partition size supported by MBR?', opts: ['1 TB', '2 TB', '4 TB', 'Unlimited'], answer: 1, exp: 'MBR (Master Boot Record) supports a maximum disk size of 2 TB due to 32-bit LBA addressing. For drives larger than 2TB, GPT (GUID Partition Table) with UEFI is required.', domain: 'D3' },
  { q: 'An employee works from home and needs encrypted access to corporate file shares. What solution should be implemented?', opts: ['Direct internet access', 'VPN connection to corporate network', 'Port forwarding on home router', 'Public cloud storage'], answer: 1, exp: 'A VPN creates an encrypted tunnel between the remote worker and the corporate network, providing secure access to internal resources as if they were on-site.', domain: 'D1' },
  { q: 'Which cloud service model gives the customer MOST control over the underlying infrastructure?', opts: ['SaaS', 'PaaS', 'IaaS', 'DBaaS'], answer: 2, exp: 'IaaS (Infrastructure as a Service) gives customers control over VMs, OS, networking, and storage. PaaS manages the OS for you. SaaS manages everything — customer only controls data and configuration.', domain: 'D4' },
  { q: 'A mobile device has sensitive corporate email. The device is lost. What MDM action should be taken?', opts: ['Locate device and wait', 'Remote wipe the device', 'Change the email password only', 'Notify the user'], answer: 1, exp: 'Remote wipe erases all data on the device to prevent unauthorized access to corporate data. Modern MDM can selectively wipe only corporate data (MAM approach) while preserving personal data.', domain: 'D1' },
  { q: 'What does the 3-2-1 backup rule specify?', opts: ['3 weekly backups, 2 monthly, 1 annual', '3 copies of data, on 2 different media types, with 1 copy offsite', '3 daily, 2 weekly, 1 monthly backup rotation', '3 incremental, 2 differential, 1 full backup cycle'], answer: 1, exp: 'The 3-2-1 rule: keep 3 total copies of data, on 2 different types of storage media, with at least 1 copy stored offsite (or in cloud). Protects against device failure, local disasters, and theft.', domain: 'D4' },
  { q: 'Which type of hypervisor runs directly on hardware without a host operating system?', opts: ['Type 2 hypervisor', 'Type 1 hypervisor (bare metal)', 'Container runtime', 'Emulator'], answer: 1, exp: 'Type 1 (bare-metal) hypervisors run directly on hardware: VMware ESXi, Microsoft Hyper-V (server), KVM. Type 2 runs as an application on a host OS: VMware Workstation, VirtualBox. Type 1 = better performance.', domain: 'D4' },
  { q: 'A Windows computer randomly shuts down after a few minutes of use, especially during demanding tasks. What is the most likely cause?', opts: ['RAM failure', 'Overheating (thermal shutdown protection)', 'PSU failure', 'Malware infection'], answer: 1, exp: 'Thermal shutdown protection triggers automatic shutoff when CPU/GPU temperatures exceed safe limits. This pattern (fine at first, shuts off under load) indicates overheating. Check fans, clean dust, reapply thermal paste.', domain: 'D3' },
  { q: 'Which port is used by SSH for secure remote administration?', opts: ['21', '22', '23', '3389'], answer: 1, exp: 'SSH uses port 22. It provides encrypted command-line remote access. Telnet (port 23) is unencrypted and deprecated. RDP (3389) is for Windows graphical remote access. FTP uses 21/20.', domain: 'D2' },
  { q: 'An M.2 SSD is not detected after installation in a new slot. What is the most likely cause?', opts: ['Wrong driver installed', 'Slot supports SATA M.2 but drive is NVMe', 'RAID configuration prevents detection', 'BIOS update required only'], answer: 1, exp: 'M.2 slots can be SATA-only, NVMe-only, or both. An NVMe drive in a SATA-only M.2 slot will not be detected. Check motherboard manual for each slot\'s supported protocols.', domain: 'D3' },
  { q: 'Which laser printer component bonds toner to paper using heat and pressure?', opts: ['Drum', 'Transfer belt', 'Fuser', 'Developer'], answer: 2, exp: 'The fuser assembly uses heat (180°C+) and pressure rollers to permanently bond toner particles to paper. Fuser issues cause smearing (not hot enough) or ghost images (worn, residual toner).', domain: 'D3' },
  { q: 'A computer randomly shuts off during gaming but runs fine at idle. What should be checked FIRST?', opts: ['RAM modules with memtest86', 'CPU and GPU temperatures with HWMonitor', 'HDD health with SMART data', 'PSU voltage rails with multimeter'], answer: 1, exp: 'Random shutdowns under heavy load are a classic symptom of thermal shutdown protection activating. Check temps with HWMonitor, clean dust from heatsinks, verify fan operation, and reapply thermal paste if needed.', domain: 'D3' },
  { q: 'An M.2 SSD is installed but not detected in BIOS. The motherboard manual shows that slot supports SATA M.2 only. What is the issue?', opts: ['Driver not installed', 'NVMe SSD in SATA-only M.2 slot', 'BIOS needs update', 'SSD power connector missing'], answer: 1, exp: 'M.2 slots can support SATA, NVMe, or both. An NVMe drive in a SATA-only slot will not be detected. Check the motherboard manual for each slot supported protocols before purchasing drives.', domain: 'D3' },
  { q: 'A display shows content only when a flashlight is held up to it. What has failed?', opts: ['LCD panel (cracked)', 'GPU driver', 'Video cable', 'Backlight / backlight inverter'], answer: 3, exp: 'Faint visible image with flashlight = display panel is functional but backlight has failed. LED backlights fail or CCFL backlight (older LCDs) with inverter fail. GPU/cable issues typically show no image or corruption.', domain: 'D3' },
  { q: 'A Windows 11 upgrade fails because the PC does not meet requirements. Which TWO hardware requirements are most commonly missing on older PCs?', opts: ['TPM 2.0 and Secure Boot capability', 'At least 8GB RAM and discrete GPU', 'USB 3.0 ports and SSD storage', '64-bit CPU and UEFI only'], answer: 0, exp: 'Windows 11 requires: TPM 2.0, Secure Boot enabled, 64-bit CPU (8th gen Intel / Ryzen 2000+), 4GB RAM, 64GB storage. TPM 2.0 and Secure Boot are the most commonly missing requirements on older hardware.', domain: 'D3' },
  { q: 'An inkjet printer has not been used for two months and now prints faded, streaky output. What is the most likely cause?', opts: ['Toner low', 'Fuser failure', 'Ink nozzles clogged from dried ink', 'Print spooler corrupt'], answer: 2, exp: 'Inkjet nozzles clog when ink dries during periods of non-use. Run the printer\'s built-in head cleaning utility (may require multiple cycles). Prevent by printing a test page at least monthly.', domain: 'D3' },
  { q: 'A user reports that after moving to a new desk, their wired Ethernet connection stopped working. Other devices at the same switch port work fine. What should be checked FIRST on the user workstation?', opts: ['Reinstall NIC drivers', 'Check that the Ethernet cable is fully seated at both ends', 'Assign a static IP address', 'Check DNS settings'], answer: 1, exp: 'Physical layer first: a cable not fully clicked in is the most common cause of sudden connectivity loss after moving equipment. Verify the cable clicks into both the NIC and switch port before investigating further.', domain: 'D2' },
  { q: 'What type of virtualization allows multiple virtual machines to run with their own isolated OS on a single physical server?', opts: ['Containerization', 'Application virtualization', 'Full machine virtualization with hypervisor', 'Network function virtualization'], answer: 2, exp: 'Full machine virtualization (Type 1 or Type 2 hypervisor) allows each VM to run its own complete OS independently. Containers share the host OS kernel. Application virtualization isolates individual apps.', domain: 'D4' },
  { q: 'A user calls to report they cannot access their files on the network share. Other users can access it fine. What should be checked?', opts: ['Network switch port', 'User account NTFS permissions on the shared folder', 'DNS server', 'Switch VLAN configuration'], answer: 1, exp: 'Since only one user is affected, check their NTFS permissions and share permissions on the specific folder. Effective permissions = most restrictive of share + NTFS. DENY overrides ALLOW. Check group memberships.', domain: 'D2' },
  { q: 'What does the acronym APIPA stand for and when is an APIPA address assigned?', opts: ['Advanced Protocol IP Assignment; assigned when NIC is installed', 'Automatic Private IP Addressing; assigned when DHCP server is unreachable', 'Assigned Protocol Internet Parameter Address; assigned at factory', 'Alternate Private IP Addressing; assigned for VPN connections'], answer: 1, exp: 'APIPA (Automatic Private IP Addressing) automatically assigns a 169.254.x.x/16 address when a DHCP server cannot be reached. The device can communicate only with other APIPA devices on the same subnet.', domain: 'D2' },
  { q: 'Which mobile device management approach enrolls the entire device including personal apps and data?', opts: ['MAM only', 'MDM (Mobile Device Management)', 'BYOD without management', 'App wrapping only'], answer: 1, exp: 'MDM enrolls the entire device, enabling full management: remote wipe, enforce encryption, manage all apps, screen lock policies. MAM manages only corporate apps. MDM is appropriate for company-owned devices.', domain: 'D1' },
  { q: 'A user reports their laptop battery drains in 2 hours instead of the usual 8 hours. What should be checked?', opts: ['RAM usage', 'Background apps, screen brightness, battery health (powercfg /batteryreport)', 'Network driver', 'Hard drive health'], answer: 1, exp: 'Run powercfg /batteryreport for battery health history. Check: background apps (Task Manager), screen brightness (major drain), Wi-Fi/Bluetooth enabled unnecessarily, battery wear level. Aging batteries lose capacity.', domain: 'D1' },
  { q: 'A technician needs to deploy a Windows image to 50 new workstations on the network. Which technology is BEST suited?', opts: ['Manual installation from USB', 'PXE network boot with WDS or MDT', 'Cloud restore from OneDrive', 'System image recovery from a single USB drive'], answer: 1, exp: 'PXE (Preboot Execution Environment) boot pulls an installation image from a network server like Windows Deployment Services or MDT, allowing mass deployment with no per-machine USB media required.', domain: 'D4' },
  { q: 'A user reports their iPhone will not charge despite using a known-good cable and charger. What should the technician check FIRST before recommending repair?', opts: ['Replace the battery', 'Clean lint and debris out of the Lightning/USB-C port', 'Restore the device to factory settings', 'Replace the phone'], answer: 1, exp: 'Lint and pocket debris frequently pack into charging ports and prevent contact. A wooden toothpick or non-metallic tool can carefully remove debris. This is the simplest and most common fix before assuming hardware failure.', domain: 'D2' },
  { q: 'A technician is configuring a small office router and wants only specific company laptops to be able to connect to Wi-Fi. Which feature should be configured?', opts: ['DHCP reservation', 'MAC address filtering', 'Static IP only', 'WPS push button'], answer: 1, exp: 'MAC address filtering allows only the listed MAC addresses to associate with the wireless network. It is not foolproof (MAC addresses can be spoofed) but provides a basic layer of access control.', domain: 'D2' },
  { q: 'Which connector is found on a standard external monitor that supports both audio and 4K video over a single cable?', opts: ['VGA', 'DVI-D', 'HDMI', 'PS/2'], answer: 2, exp: 'HDMI (High-Definition Multimedia Interface) carries both video and audio in one cable and supports 4K and higher resolutions in modern versions (HDMI 2.0+). VGA and DVI-D are video only.', domain: 'D2' },
  { q: 'A user reports that their Wi-Fi works in some rooms but disconnects in others. The router is in a basement office. What is the BEST solution?', opts: ['Buy a faster internet plan', 'Add a wireless mesh node or access point on the upper floors', 'Replace the user laptop', 'Change to a higher channel number'], answer: 1, exp: 'Coverage dead zones are usually a placement and signal-strength problem. Adding mesh nodes or APs extends coverage. A faster ISP plan does not change Wi-Fi range, and laptops are rarely the issue if multiple devices have problems.', domain: 'D2' },
  { q: 'Which mobile synchronization method requires NO cables and uses the device internet connection to sync mail, contacts, and calendar?', opts: ['USB tethering', 'Cloud-based sync (Exchange, iCloud, Google)', 'NFC pairing', 'Bluetooth file transfer'], answer: 1, exp: 'Cloud-based sync (Microsoft 365/Exchange, iCloud, Google Workspace) automatically synchronizes mail, contacts, and calendar over the internet without cables. Most enterprise mobile deployments rely on this.', domain: 'D1' },
  { q: 'A technician must support a laptop that is being used in a chemical lab. Which laptop type is MOST appropriate?', opts: ['Ultrabook', 'Standard consumer laptop', 'Ruggedized laptop with sealed keyboard and reinforced chassis', 'Gaming laptop'], answer: 2, exp: 'Ruggedized laptops have sealed keyboards, reinforced cases, shock-resistant drives, and often meet MIL-STD specs. They are designed for harsh environments like labs, construction sites, and field service.', domain: 'D1' },
  { q: 'Which two TCP ports are used by FTP?', opts: ['20 and 21', '22 and 23', '25 and 110', '80 and 443'], answer: 0, exp: 'FTP uses TCP port 21 for the control channel and TCP port 20 for the data channel in active mode. Passive mode uses port 21 for control and a high-numbered ephemeral port for data.', domain: 'D2' },
  { q: 'A technician needs to connect a high-resolution external monitor and a USB-C dock to a new laptop using a single cable that carries video, data, and power. Which port is BEST suited?', opts: ['USB 2.0 Type-A', 'HDMI', 'Thunderbolt 3 / USB4', 'PS/2'], answer: 2, exp: 'Thunderbolt 3 and USB4 over USB-C carry DisplayPort video, USB data, and up to 100W of Power Delivery on one cable. HDMI carries audio and video but no data or power. USB Type-A and PS/2 cannot drive a 4K display.', domain: 'D1' },
  { q: 'A user has a laptop battery that is visibly bulging and the case no longer closes flat. What is the appropriate response?', opts: ['Continue using the laptop until the battery dies completely', 'Stop using the laptop, store it somewhere safe and non-flammable, and arrange for proper disposal and battery replacement', 'Charge the battery fully to relieve pressure', 'Place the battery in a freezer'], answer: 1, exp: 'A swollen lithium-ion battery is a thermal-runaway and fire hazard. Power down, isolate from flammables, and replace the battery using proper handling. Never puncture, charge, freeze, or otherwise stress a swollen pack.', domain: 'D1' },
  { q: 'Which Windows command releases the current DHCP-assigned IP address from all adapters?', opts: ['ipconfig /flushdns', 'ipconfig /release', 'ipconfig /registerdns', 'ipconfig /displaydns'], answer: 1, exp: 'ipconfig /release returns the current DHCP lease, and ipconfig /renew requests a new lease. /flushdns clears the DNS resolver cache, and /registerdns refreshes the dynamic DNS registration.', domain: 'D2' },
  { q: 'A help desk ticket states: "Wi-Fi works in the living room but disconnects in the back bedroom." Which BEST step should the technician take next?', opts: ['Reinstall the user\'s operating system', 'Survey signal strength in both locations and consider relocating the access point or adding a mesh node', 'Replace the user\'s laptop NIC', 'Change the SSID name'], answer: 1, exp: 'Symptoms differ by location, not by device, so the cause is wireless coverage. A site survey identifies the dead spot and supports either relocation of the AP or a mesh node to extend coverage. Replacing user hardware does not address coverage geometry.', domain: 'D2' },
  { q: 'A printer in a small office is shared from one user\'s Windows PC. When that PC is asleep, no one else can print. What is the BEST permanent fix?', opts: ['Reinstall the printer drivers on every PC', 'Connect the printer directly to the network and install it as a network printer on each PC', 'Tell users not to print when the host is asleep', 'Disable sleep mode on the host PC indefinitely'], answer: 1, exp: 'A network-attached printer is independent of any single workstation, so it remains available even if a user\'s PC is off or asleep. Disabling sleep is wasteful and fragile, and reinstalling drivers does not change the dependency on the host.', domain: 'D3' },
  { q: 'Which printer technology heats a thermal printhead against a ribbon to transfer wax-based ink onto labels and receipts?', opts: ['Inkjet', 'Laser', 'Thermal transfer', '3D printer'], answer: 2, exp: 'Thermal transfer printers melt wax or resin from a ribbon onto media. They are common for shipping labels and barcodes that must remain legible over time. Direct thermal printers, by contrast, use no ribbon and rely on heat-sensitive paper.', domain: 'D3' },
  { q: 'A user calls and reports that their Windows PC displays "No bootable device" at startup. Internal drives test fine in another computer. What should the technician check FIRST?', opts: ['Replace the motherboard', 'Verify the boot order in UEFI/BIOS and that the correct drive is set as first boot device', 'Reinstall Windows', 'Replace the CPU'], answer: 1, exp: 'A drive that works in another system is healthy. The most common cause of this message after BIOS changes or a USB being left plugged in is an incorrect boot order. Confirm the OS drive is first and Secure Boot/CSM settings match the installation.', domain: 'D3' },
  { q: 'A user reports that touch gestures on a Windows laptop\'s precision touchpad no longer work, although the touchpad cursor still moves. Where should the technician check FIRST?', opts: ['Replace the touchpad hardware', 'Verify gestures are enabled under Settings > Bluetooth & devices > Touchpad and that the latest driver is installed', 'Reinstall Windows', 'Replace the laptop'], answer: 1, exp: 'Touchpad gesture settings and the precision touchpad driver are usually the root cause. The Settings page exposes per-gesture toggles, and an outdated driver after an update can disable advanced gestures. Hardware replacement is premature.', domain: 'D1' },
  { q: 'A user is asked to print sensitive payroll information and wants to ensure that no one else can pick up the documents from the shared printer. Which printer feature BEST addresses this?', opts: ['Duplex printing', 'Secure print / pull printing with PIN release', 'Toner save mode', 'Tray selection'], answer: 1, exp: 'Secure print holds the job at the device until the user authenticates at the printer (PIN, badge, or smart card) and releases the print. Duplex and toner save do not address confidentiality.', domain: 'D3' },
  { q: 'A user reports that their Windows laptop will not connect to the corporate Wi-Fi after rejoining the domain, although other users connect fine. The Wi-Fi adapter is enabled and signal is strong. What should the technician verify FIRST?', opts: ['That the laptop has a discrete GPU', 'That the laptop trusts the corporate Wi-Fi server certificate and the user\'s credentials are not locked out', 'That the laptop has been rebooted ten times', 'That the laptop is plugged into Ethernet'], answer: 1, exp: 'Enterprise Wi-Fi using 802.1X typically requires the client to validate the RADIUS server certificate and provide valid credentials. After a rejoin, certificate trust or stale cached credentials are the common failures. Verify cert trust and account lockout status.', domain: 'D1' },
  { q: 'Which connector and protocol combination is REQUIRED to drive a 144 Hz 1440p gaming monitor from a desktop GPU?', opts: ['DisplayPort 1.2 or higher, or HDMI 2.0 or higher', 'VGA only', 'DVI-A', 'Composite video'], answer: 0, exp: 'High refresh-rate 1440p needs the bandwidth of DisplayPort 1.2 or higher or HDMI 2.0 or higher. VGA is analog and capped well below this, DVI-A is analog, and composite is standard-definition only.', domain: 'D3' },
  { q: 'A technician installs a matched pair of RAM modules, but the system reports they are running in single-channel mode. What is the MOST likely cause?', opts: ['The modules are different capacities', 'The modules are not in the correct color-coded paired slots', 'The RAM is faulty', 'The CPU does not support dual-channel'], answer: 1, exp: 'Dual-channel mode requires modules in the matching slots indicated by the motherboard (often color-coded, e.g., A2/B2). Installing them in the wrong pair forces single-channel operation. Check the motherboard manual for the correct slots.', domain: 'D3' },
  { q: 'A DDR4 memory module will not seat in a motherboard memory slot. What is the MOST likely reason?', opts: ['The slot is for a different DDR generation', 'The module needs more force', 'The BIOS must be updated first', 'The module is simply upside down'], answer: 0, exp: 'DDR3, DDR4, and DDR5 modules have the notch (key) in different positions and are physically incompatible. A DDR4 module cannot seat in a DDR3 or DDR5 slot. Never force a module — verify the generation the board supports.', domain: 'D3' },
  { q: 'Which type of memory can detect and correct single-bit errors and is commonly used in servers?', opts: ['Non-ECC DDR4', 'ECC RAM', 'VRAM', 'Flash memory'], answer: 1, exp: 'ECC (Error-Correcting Code) memory uses an extra chip to detect and correct single-bit errors, preventing crashes and data corruption. It is standard in servers and workstations where reliability is critical; most consumer boards do not support it.', domain: 'D3' },
  { q: 'Before purchasing a replacement CPU, which motherboard characteristic MUST a technician confirm for compatibility?', opts: ['The number of SATA ports', 'The CPU socket type and chipset support', 'The installed RAM capacity', 'The power supply wattage'], answer: 1, exp: 'A CPU must match the motherboard physical socket (e.g., LGA1700, AM5) and be supported by the chipset, sometimes after a BIOS update. RAM and PSU matter for the build overall but do not determine CPU-to-board fit.', domain: 'D3' },
  { q: 'A user needs the fastest possible transfer speed for an external SSD. Which connection should the technician recommend?', opts: ['USB 2.0 (480 Mbps)', 'USB 3.2 Gen 1 (5 Gbps)', 'USB 3.2 Gen 2 (10 Gbps)', 'FireWire 400'], answer: 2, exp: 'USB 3.2 Gen 2 provides 10 Gbps — double the 5 Gbps of USB 3.2 Gen 1 and far above USB 2.0 at 480 Mbps. For an external SSD, matching drive and port to the highest common standard maximizes throughput.', domain: 'D3' },
  { q: 'Which power supply connector provides dedicated power to the CPU on a modern motherboard?', opts: ['24-pin ATX main connector', '4/8-pin EPS12V connector', '6/8-pin PCIe connector', 'SATA power connector'], answer: 1, exp: 'The 4-pin or 8-pin EPS12V connector near the CPU socket supplies the processor. The 24-pin powers the board overall, 6/8-pin PCIe powers graphics cards, and SATA power connectors feed drives.', domain: 'D3' },
  { q: 'After installing a high-end graphics card, a desktop shuts down abruptly during gaming but runs fine at idle. What should the technician check FIRST?', opts: ['The monitor refresh rate', 'Whether the power supply wattage is sufficient for the new load', 'The DNS configuration', 'The installed Windows edition'], answer: 1, exp: 'A GPU sharply increases power draw under load. If the PSU cannot deliver enough wattage on the 12V rail, the system shuts down when demand peaks. Verify the PSU meets the GPU manufacturer recommended wattage.', domain: 'D3' },
  { q: 'A user streams 4K video and wants the fastest, least-congested wireless connection. Which choice is BEST?', opts: ['2.4 GHz band with 802.11g', '5 GHz or 6 GHz band with Wi-Fi 6', 'A longer antenna on 2.4 GHz', 'Disabling encryption for speed'], answer: 1, exp: 'The 5 GHz and 6 GHz bands offer more non-overlapping channels and higher throughput than the crowded 2.4 GHz band, and Wi-Fi 6 (802.11ax) improves speed and efficiency further. Never disable encryption for performance.', domain: 'D2' },
  { q: 'Why might a technician deliberately choose the 2.4 GHz Wi-Fi band over 5 GHz for a particular device?', opts: ['2.4 GHz is always faster', '2.4 GHz has greater range and penetrates walls better', '2.4 GHz is inherently more secure', '2.4 GHz uses less electricity'], answer: 1, exp: 'Lower-frequency 2.4 GHz signals travel farther and pass through walls and floors better than 5 GHz. The trade-off is lower throughput and more congestion. Use 2.4 GHz for distant or obstructed devices.', domain: 'D2' },
  { q: 'Which cable type connects two PCs directly NIC-to-NIC on legacy equipment that lacks auto-MDI-X?', opts: ['Straight-through cable', 'Crossover cable', 'Rollover (console) cable', 'Coaxial cable'], answer: 1, exp: 'A crossover cable swaps the transmit and receive pairs so two like devices can communicate directly. Straight-through cables connect unlike devices (PC to switch). Modern auto-MDI-X gear removes the need for crossover cables.', domain: 'D2' },
  { q: 'Network cabling must run through the space above a drop ceiling that is used for air circulation. Which cable rating is REQUIRED?', opts: ['Riser-rated cable', 'Plenum-rated cable', 'Direct-burial cable', 'Standard patch cable'], answer: 1, exp: 'Plenum-rated cable uses a fire-resistant, low-smoke jacket required by fire code in air-handling (plenum) spaces. Standard PVC cable releases toxic smoke when burning and is not permitted in those areas.', domain: 'D2' },
  { q: 'A network link must span 2 km between buildings and be immune to electromagnetic interference. Which media is BEST?', opts: ['Cat 6 UTP copper', 'Single-mode fiber optic', 'Coaxial cable', 'Cat 5e STP copper'], answer: 1, exp: 'Fiber optic transmits light, so it is immune to EMI and supports very long distances — single-mode fiber spans many kilometers. Copper runs (UTP/STP) are limited to about 100 m and are susceptible to interference.', domain: 'D2' },
  { q: 'A technician must verify that a web service is reachable over its secure, encrypted port. Which port should be tested?', opts: ['80', '443', '21', '23'], answer: 1, exp: 'HTTPS uses TCP port 443 for encrypted web traffic. Port 80 is unencrypted HTTP, 21 is FTP control, and 23 is Telnet. A secure site must be reachable on 443.', domain: 'D2' },
  { q: 'Which port and protocol does Windows use for file and printer sharing on a local network?', opts: ['SMB on port 445', 'FTP on port 21', 'SNMP on port 161', 'RDP on port 3389'], answer: 0, exp: 'SMB (Server Message Block) uses TCP port 445 for Windows file and printer sharing. Blocking 445 at the perimeter firewall is a common ransomware mitigation. RDP (3389) is remote desktop, not file sharing.', domain: 'D3' },
  { q: 'A business must print multipart carbon-copy forms such as invoices. Which printer type is REQUIRED?', opts: ['Laser printer', 'Inkjet printer', 'Impact (dot-matrix) printer', 'Thermal printer'], answer: 2, exp: 'Only impact printers physically strike the paper through a ribbon, so the force transfers through multipart (carbon or carbonless) forms. Laser, inkjet, and thermal printers cannot produce multiple copies in one pass.', domain: 'D3' },
  { q: 'A user wants to connect a laptop to the internet using a smartphone cellular data connection. Which smartphone feature should be enabled?', opts: ['Airplane mode', 'Mobile hotspot / tethering', 'Do Not Disturb', 'NFC'], answer: 1, exp: 'Mobile hotspot (tethering) shares the phone cellular connection with other devices over Wi-Fi, USB, or Bluetooth. Watch carrier data limits. NFC is for very short-range contactless tasks, not internet sharing.', domain: 'D1' },
  { q: 'Which short-range wireless technology enables contactless mobile payments and tap-to-pair?', opts: ['Bluetooth', 'NFC', 'Infrared', 'Wi-Fi Direct'], answer: 1, exp: 'NFC (Near Field Communication) works over a few centimeters and powers mobile payments (Apple Pay, Google Pay) and quick pairing. Its very short range is itself a security feature against remote interception.', domain: 'D1' },
  { q: 'A small server must stay running through brief power outages and also be protected from voltage spikes. Which device provides BOTH?', opts: ['Surge protector', 'Uninterruptible power supply (UPS)', 'Basic power strip', 'Line splitter'], answer: 1, exp: 'A UPS contains a battery that maintains power during outages and conditions the line against surges and sags, allowing a graceful shutdown. A surge protector guards against spikes only and provides no battery runtime.', domain: 'D3' },
  { q: 'A laser printer produces completely blank pages. Which stage of the imaging process is the MOST likely point of failure?', opts: ['The fuser assembly', 'The charging, exposing (laser), or transfer stage', 'The duplexer', 'The paper tray sensor'], answer: 1, exp: 'Blank pages mean toner never reaches or transfers to the paper — a charging, exposing (laser), or transfer failure. Smearing points to the fuser; ghosting points to a worn cleaning stage. Match the symptom to the EP step.', domain: 'D3' },
  { q: 'A technician must dispose of used laser toner cartridges and old lithium-ion batteries. What is the correct guidance?', opts: ['Place them in normal trash', 'Follow local regulations and the SDS — use approved recycling or hazardous-waste programs', 'Incinerate them on site', 'Bury them away from the building'], answer: 1, exp: 'Toner and batteries are regulated waste. The Safety Data Sheet (SDS) and local regulations specify proper disposal — typically manufacturer take-back or hazardous-waste recycling. Never trash, burn, or bury them.', domain: 'D1' },
  { q: 'A network admin wants each Wi-Fi user to authenticate with their own corporate credentials rather than a shared password. Which configuration provides this?', opts: ['WPA2-Personal with a strong PSK', 'WPA3-Personal with SAE', 'WPA2/WPA3-Enterprise with 802.1X + RADIUS', 'A hidden SSID with MAC filtering'], answer: 2, exp: 'Enterprise mode authenticates each user against a RADIUS server using 802.1X (often tied to Active Directory). When an employee leaves, only their account is disabled — the wireless password does not change. PSK requires changing the network password to revoke access.', domain: 'D2' },
  { q: 'Which statement about hiding the SSID and enabling MAC filtering on a wireless router is MOST accurate?', opts: ['They provide strong encryption of wireless traffic', 'They are weak controls because both can be discovered or spoofed', 'They replace the need for WPA3', 'They block all unauthorized devices automatically'], answer: 1, exp: 'Hidden SSIDs leak through client probe requests; MAC addresses appear in plain wireless headers and are trivially spoofable. They add minor inconvenience for attackers but should never replace strong encryption like WPA3.', domain: 'D2' },
];
